CREATE TABLE "article" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "article_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"title" text NOT NULL,
	"slug" varchar(255) NOT NULL CONSTRAINT "article_slug_unique" UNIQUE,
	"body" text NOT NULL,
	"image_small_key" text NOT NULL,
