CREATE TABLE "audit_log" (
	"id" integer PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "audit_log_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"action" text NOT NULL,
	"actor_id" integer NOT NULL,
	"entity" text NOT NULL,
	"entity_key" text NOT NULL,
	"at" timestamp with time zone NOT NULL,
	CONSTRAINT "audit_log_action" CHECK ("action" in ('department.created', 'department.updated', 'semester.created', 'fieldOfStudy.created', 'fieldOfStudy.updated', 'staticContent.updated', 'article.createdDraft', 'article.createdPublished', 'article.published', 'article.unpublished', 'sponsor.created', 'socialEvent.created', 'publicFile.registered')),
	CONSTRAINT "audit_log_entity" CHECK ("entity" in ('Department', 'Semester', 'FieldOfStudy', 'Article', 'StaticContent', 'Sponsor', 'SocialEvent', 'PublicFile')),
	CONSTRAINT "audit_log_actor" CHECK ("actor_id" > 0)
);
