CREATE TABLE "department" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "department_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"name" text NOT NULL,
	"short_name" text NOT NULL,
	"email" text NOT NULL,
	"city" text NOT NULL CONSTRAINT "department_city_unique" UNIQUE,
	"address" text,
	"active" boolean DEFAULT true NOT NULL,
	"slack_channel" text,
	"logo_key" text,
	"latitude" double precision,
	"longitude" double precision,
	CONSTRAINT "department_name" CHECK (length("name") > 0),
