CREATE TABLE "outbox" (
	"id" integer PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "outbox_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"kind" text NOT NULL,
	"payload" jsonb NOT NULL,
	"status" "outbox_status" DEFAULT 'pending'::"outbox_status" NOT NULL,
	"attempts" integer DEFAULT 0 NOT NULL,
	"next_attempt_at" timestamp with time zone NOT NULL,
	"claim_token" uuid,
	"claimed_until" timestamp with time zone,
	"last_error" text,
	"delivered_at" timestamp with time zone,
	"created_at" timestamp with time zone NOT NULL,
	CONSTRAINT "outbox_kind" CHECK ("kind" in ('Email', 'SlackPost')),
	CONSTRAINT "outbox_payload_kind" CHECK ("payload" ->> '_tag' = "kind"),
	CONSTRAINT "outbox_attempts" CHECK ("attempts" >= 0),
	CONSTRAINT "outbox_claim" CHECK (("claim_token" is null) = ("claimed_until" is null)),
	CONSTRAINT "outbox_delivered" CHECK (("status" = 'delivered') = ("delivered_at" is not null))
);
--> statement-breakpoint
CREATE TABLE "public_file" (
	"key" text PRIMARY KEY,
	"name" varchar(255) NOT NULL,
	"content_type" text NOT NULL,
	"size" integer NOT NULL,
	"sha256" text NOT NULL,
	"uploaded_by" integer,
	"legacy_path" text CONSTRAINT "public_file_legacy_path_unique" UNIQUE,
	"uploaded_at" timestamp with time zone NOT NULL,
	"deleted_at" timestamp with time zone,
	CONSTRAINT "public_file_key_format" CHECK ("key" ~ '^[0-9a-f]{64}\.(jpg|png|webp|gif|pdf|bin)$'),
	CONSTRAINT "public_file_key_hash" CHECK (left("key", 64) = "sha256"),
	CONSTRAINT "public_file_content_type" CHECK ("content_type" in ('image/jpeg', 'image/png', 'image/webp', 'image/gif', 'application/pdf', 'application/octet-stream')),
	CONSTRAINT "public_file_size" CHECK ("size" >= 0),
	CONSTRAINT "public_file_name" CHECK (length("name") > 0)
);
--> statement-breakpoint
